String cmd = ctx.winlog.event_data.CommandLine;
String[] parts = cmd.splitOnToken(' ');
for (int i = parts.length - 1; i >= 0; i--) {
  String token = parts[i].trim();
  if (token.length() >= 16) {
    try {
      def raw = Base64.getDecoder().decode(token);
      if (raw.length >= 2) {
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k + 1 < raw.length; k += 2) {
          int lo = raw[k] & 255;
          int hi = raw[k + 1] & 255;
          sb.append((char)(lo | (hi * 256)));
        }
        String decoded = sb.toString();
        int printable = 0;
        for (int j = 0; j < decoded.length(); j++) {
          char c = decoded.charAt(j);
          if (c >= 32 && c != 127) { printable++; }
        }
        if (decoded.length() > 0 && printable * 5 >= decoded.length() * 4) {
          if (ctx.aegis == null) { ctx.aegis = new HashMap(); }
          if (ctx.aegis.powershell == null) { ctx.aegis.powershell = new HashMap(); }
          ctx.aegis.powershell.decoded_command = decoded;
          ctx.aegis.powershell.encoded_token_length = token.length();
          return;
        }
      }
    } catch (Exception e) {
      // token was not valid base64; keep scanning earlier tokens
    }
  }
}
